<script setup>
import { computed,reactive } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import AttachmentNotice from '../components/AttachmentNotice.vue'
import StatusTag from '../components/StatusTag.vue'
import { addTaskResult,hasActiveTaskResult,getTaskResultByTaskId } from '../mock/taskResults.js'
import { getSelectedStudents,getTaskById,getTaskTypeText,markTaskResultSubmitted } from '../mock/tasks.js'

const route=useRoute();const router=useRouter()
const currentStudent={id:'stu001',studentId:'2024001',name:'张三',college:'计算机学院',major:'数据科学与大数据技术'}
const task=computed(()=>getTaskById(route.params.id))
const isLeader=computed(()=>task.value?.leaderId===currentStudent.studentId)
const teamMembers=computed(()=>task.value?getSelectedStudents(task.value.taskId):[])
const existingResult=computed(()=>getTaskResultByTaskId(route.params.id))
const duplicate=computed(()=>hasActiveTaskResult(route.params.id))
const form=reactive({description:'',resultFiles:[],proofFiles:[]})
function nowText(){return new Date().toLocaleString('zh-CN',{hour12:false}).replaceAll('/','-')}
function formatSize(bytes){if(bytes>=1048576)return`${(bytes/1048576).toFixed(2)} MB`;if(bytes>=1024)return`${(bytes/1024).toFixed(2)} KB`;return`${bytes} B`}
function readFiles(event,target,category){Array.from(event.target.files||[]).forEach((file,index)=>target.push({id:`RESULT-ATT-${Date.now()}-${index}`,name:file.name,type:file.type||'未知类型',size:formatSize(file.size),uploadedAt:nowText(),mockUrl:URL.createObjectURL(file),category,description:category==='result'?'任务成果材料':'证明材料'}));event.target.value=''}
function removeFile(target,id){const file=target.find(item=>item.id===id);if(file?.mockUrl)URL.revokeObjectURL(file.mockUrl);const index=target.findIndex(item=>item.id===id);if(index>=0)target.splice(index,1)}
function validate(){if(!task.value)return'任务不存在。';if(!task.value.leaderId)return'任务尚未指定队长。';if(!isLeader.value)return'只有被指定的队长才能提交任务成果。';if(duplicate.value)return'该任务已提交成果，请勿重复提交。';if(!form.description.trim())return'请填写任务成果说明。';if(!form.resultFiles.length)return'请至少上传 1 个成果材料。';if(!Number.isFinite(Number(task.value.hours))||Number(task.value.hours)<=0)return'任务未设置有效的申请课时，请联系指导老师。';return''}
function submit(){const error=validate();if(error)return window.alert(error);const members=teamMembers.value.map(member=>({id:member.studentId,name:member.studentName,studentId:member.studentId,college:member.college||'',major:member.major||'',role:member.studentId===task.value.leaderId?'captain':'member'}));const result=addTaskResult({taskId:task.value.taskId,taskTitle:task.value.title,taskHours:Number(task.value.hours),leaderId:task.value.leaderId,leaderName:task.value.leaderName,advisorId:task.value.advisorId,advisorName:task.value.advisorName,teamMembers:members,resultDescription:form.description.trim(),resultMaterials:form.resultFiles.map(file=>({...file})),proofMaterials:form.proofFiles.map(file=>({...file}))});if(!result)return window.alert('该任务已有待处理或已确认成果，请勿重复提交。');markTaskResultSubmitted(task.value.taskId,currentStudent.studentId);window.alert('成果已提交，等待指导老师确认。');router.push(`/student/tasks/${task.value.taskId}`)}
function back(){router.push(`/student/tasks/${route.params.id}`)}
</script>

<template><main class="page"><div class="content"><template v-if="task"><header><div><p class="eyebrow">S105 · RESULT SUBMISSION</p><h1>队长上传成果</h1><p>{{ task.title }} · {{ task.taskId }}</p></div><StatusTag :status="task.status" /></header><section v-if="!isLeader" class="warning">只有当前任务指定的队长可以上传成果并发起课时申请。</section><section v-else-if="duplicate" class="warning">该任务已提交成果申请，请勿重复提交。</section><section class="card"><h2>任务基本信息</h2><dl class="grid"><div><dt>任务名称</dt><dd>{{ task.title }}</dd></div><div><dt>任务类型</dt><dd>{{ getTaskTypeText(task.taskType) }}</dd></div><div><dt>指导老师</dt><dd>{{ task.advisorName }}</dd></div><div><dt>申请课时</dt><dd>{{ task.hours }} 课时（只读）</dd></div><div class="wide"><dt>成果提交要求</dt><dd>{{ task.resultRequirement }}</dd></div></dl></section><section class="card"><h2>队长信息</h2><dl class="grid"><div><dt>姓名</dt><dd>{{ currentStudent.name }}</dd></div><div><dt>学号</dt><dd>{{ currentStudent.studentId }}</dd></div><div><dt>任务队长</dt><dd>{{ task.leaderName }}</dd></div></dl></section><section class="card"><h2>团队成员信息</h2><div class="table-wrap"><table><thead><tr><th>姓名</th><th>学号</th><th>学院</th><th>专业</th><th>角色</th></tr></thead><tbody><tr v-for="member in teamMembers" :key="member.studentId"><td>{{ member.studentName }}</td><td>{{ member.studentId }}</td><td>{{ member.college||'--' }}</td><td>{{ member.major||'--' }}</td><td>{{ member.studentId===task.leaderId?'队长':'成员' }}</td></tr></tbody></table></div></section><section class="card"><h2>任务成果说明</h2><textarea v-model="form.description" rows="6" :disabled="!isLeader||duplicate" placeholder="请说明任务完成情况、团队分工和主要成果。"></textarea></section><section class="card"><h2>成果材料上传</h2><AttachmentNotice title="成果材料" description="请选择成果报告、作品、数据文件或成果截图。当前为 Mock 上传。" :required="true" :accept-types="['PDF','Word','Excel','PPT','图片','压缩包']" /><input class="picker" type="file" multiple :disabled="!isLeader||duplicate" @change="readFiles($event,form.resultFiles,'result')" /><div class="files"><article v-for="file in form.resultFiles" :key="file.id"><div><strong>{{ file.name }}</strong><small>{{ file.type }} · {{ file.size }} · {{ file.uploadedAt }}</small></div><button @click="removeFile(form.resultFiles,file.id)">删除</button></article></div></section><section class="card"><h2>证明材料上传</h2><AttachmentNotice title="证明材料" description="可补充上传过程记录、参与证明或其他辅助材料。" :required="false" :accept-types="['PDF','Word','图片']" /><input class="picker" type="file" multiple :disabled="!isLeader||duplicate" @change="readFiles($event,form.proofFiles,'proof')" /><div class="files"><article v-for="file in form.proofFiles" :key="file.id"><div><strong>{{ file.name }}</strong><small>{{ file.type }} · {{ file.size }} · {{ file.uploadedAt }}</small></div><button @click="removeFile(form.proofFiles,file.id)">删除</button></article></div></section><div class="actions"><button class="back" @click="back">返回</button><button class="submit" :disabled="!isLeader||duplicate" @click="submit">提交成果</button></div></template><section v-else class="card empty">任务不存在。<button @click="back">返回</button></section></div></main></template>

<style scoped>.page{min-height:100vh;padding:40px 24px;background:#f3f6fb}.content{width:min(100%,980px);margin:auto}header{display:flex;justify-content:space-between;gap:20px;margin-bottom:20px}h1{margin:0}header p{color:#64748b}.eyebrow{margin:0 0 6px;color:#2563eb!important;font-size:12px;font-weight:800;letter-spacing:.12em}.warning{margin-bottom:18px;padding:15px;border-radius:10px;color:#b91c1c;background:#fee2e2}.card{margin-bottom:18px;padding:22px;border:1px solid #e2e8f0;border-radius:14px;background:#fff}.card h2{margin:0 0 18px}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:18px;margin:0}.wide{grid-column:1/-1}dt{color:#64748b;font-size:13px}dd{margin:5px 0 0;font-weight:600;line-height:1.7}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse}th,td{padding:11px;border-bottom:1px solid #e2e8f0;text-align:left}th{background:#f8fafc}textarea,.picker{width:100%;padding:11px;border:1px solid #cbd5e1;border-radius:9px;font:inherit}.picker{margin-top:16px}.files{display:grid;gap:10px;margin-top:14px}.files article{display:flex;justify-content:space-between;gap:12px;padding:13px;border:1px solid #e2e8f0;border-radius:9px;background:#f8fafc}.files small{display:block;margin-top:5px;color:#64748b}.files button{padding:7px 11px;border:1px solid #fecaca;border-radius:8px;color:#b91c1c;background:#fff;font-weight:700}.actions{display:flex;justify-content:flex-end;gap:10px}.actions button,.empty button{padding:10px 18px;border-radius:9px;font:inherit;font-weight:700}.back{border:1px solid #cbd5e1;background:#fff}.submit{border:0;color:#fff;background:#2563eb}.submit:disabled{opacity:.5}.empty{text-align:center}@media(max-width:650px){.page{padding:24px 14px}header{flex-direction:column}.grid{grid-template-columns:1fr}.wide{grid-column:auto}.files article{flex-direction:column}}</style>
